#include <iostream>
class Counter {
    int n;
public:
    Counter(int n = 0) : n(n) {}
    Counter& operator++() { ++n; return *this; } // prefix
    Counter operator++(int) { Counter t = *this; ++n; return t; } // postfix
    int get() const { return n; }
};
int main() {
    Counter c(5);
    Counter a = ++c;
    Counter b = c++;
    std::cout << a.get() << " " << b.get() << " " << c.get() << std::endl;
}

#include <iostream>
const int MAX = 5;
class Stack {
    int data[MAX];
    int top;
public:
    Stack() : top(-1) {}
    bool push(int v) {
        if (top >= MAX - 1) return false;
        data[++top] = v;
        return true;
    }
    int pop() { return (top < 0) ? -1 : data[top--]; }
    int peek() const { return (top < 0) ? -1 : data[top]; }
};
int main() {
    Stack s;
    s.push(10); s.push(20); s.push(30);
    std::cout << s.pop() << " " << s.peek() << " ";
    s.push(40);
    std::cout << s.pop() << std::endl;
}

