#include <iostream>
int compute(int n) {
    static int callCount = 0;
    ++callCount;
    if (n <= 0) return callCount;
    return compute(n - 1);
}
int main() {
    std::cout << compute(3) << " ";
    std::cout << compute(2) << std::endl;
}

#include <iostream>
class Matrix2x2 {
    double a, b, c, d;
public:
    Matrix2x2(double a, double b, double c, double d) : a(a), b(b), c(c), d(d) {}
    Matrix2x2 operator*(const Matrix2x2& m) const {
        return Matrix2x2(a*m.a + b*m.c, a*m.b + b*m.d, c*m.a + d*m.c, c*m.b + d*m.d);
    }
    double det() const { return a * d - b * c; }
};
int main() {
    Matrix2x2 I(1, 0, 0, 1);
    Matrix2x2 A(2, 3, 1, 4);
    Matrix2x2 B = A * I;
    std::cout << B.det() << " " << (A * A).det() << std::endl;
}

#include <iostream>
struct Node {
    int val;
    Node* next;
    Node(int v, Node* n = nullptr) : val(v), next(n) {}
};
int sumList(Node* head) {
    if (!head) return 0;
    return head->val + sumList(head->next);
}
int main() {
    Node* list = new Node(1, new Node(2, new Node(3, new Node(4, new Node(5)))));
    std::cout << sumList(list) << std::endl;
}

